import { Router, type Request, type Response } from 'express';
import crypto from 'node:crypto';

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags?: string[];
  createdAt: string;
}

export interface CreateBookmarkInput {
  url: string;
  title?: string;
  tags?: string[];
}

export function isCreateBookmarkInput(value: unknown): value is CreateBookmarkInput {
  if (typeof value !== 'object' || value === null) {
    return false;
  }

  const record = value as Record<string, unknown>;

  if (typeof record.url !== 'string' || record.url.trim().length === 0) {
    return false;
  }

  if (record.title !== undefined && typeof record.title !== 'string') {
    return false;
  }

  if (record.tags !== undefined) {
    if (!Array.isArray(record.tags)) {
      return false;
    }
    for (const tag of record.tags) {
      if (typeof tag !== 'string') {
        return false;
      }
    }
  }

  return true;
}

export const bookmarks: Bookmark[] = [];

export function clearBookmarks(): void {
  bookmarks.length = 0;
}

export const bookmarksRouter = Router();

bookmarksRouter.post(['/', '/api/v1/bookmarks'], (req: Request, res: Response): void => {
  const body: unknown = req.body;

  if (!isCreateBookmarkInput(body)) {
    res.status(400).json({
      error: 'Invalid request body',
      message: 'Body must include a valid "url" string and optional "title" (string) and "tags" (string[])',
    });
    return;
  }

  const newBookmark: Bookmark = {
    id: crypto.randomUUID(),
    url: body.url,
    ...(body.title !== undefined ? { title: body.title } : {}),
    ...(body.tags !== undefined ? { tags: body.tags } : {}),
    createdAt: new Date().toISOString(),
  };

  bookmarks.push(newBookmark);

  res.status(201).json(newBookmark);
});

export default bookmarksRouter;

