import { describe, it, expect, beforeEach } from 'vitest';
import request from 'supertest';
import { app } from '../src/app.js';
import { clearBookmarks } from '../src/routes/bookmarks.js';

describe('POST /api/v1/bookmarks', () => {
  beforeEach(() => {
    clearBookmarks();
  });

  it('creates a bookmark with only url', async () => {
    const res = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'https://example.com' });

    expect(res.status).toBe(201);
    const body: unknown = res.body;
    expect(body).toBeTypeOf('object');
    expect(body).not.toBeNull();
    const record = body as Record<string, unknown>;
    expect(record.id).toBeTypeOf('string');
    expect(record.url).toBe('https://example.com');
    expect(record.createdAt).toBeTypeOf('string');
  });

  it('creates a bookmark with url, title, and tags', async () => {
    const payload = {
      url: 'https://example.com/docs',
      title: 'Documentation',
      tags: ['typescript', 'docs'],
    };

    const res = await request(app)
      .post('/api/v1/bookmarks')
      .send(payload);

    expect(res.status).toBe(201);
    const body: unknown = res.body;
    const record = body as Record<string, unknown>;
    expect(record.url).toBe(payload.url);
    expect(record.title).toBe(payload.title);
    expect(record.tags).toEqual(payload.tags);
  });

  it('returns 400 when url is invalid or missing', async () => {
    const resInvalid = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'not-a-valid-url' });

    expect(resInvalid.status).toBe(400);

    const resEmpty = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: '' });

    expect(resEmpty.status).toBe(400);

    const resMissing = await request(app)
      .post('/api/v1/bookmarks')
      .send({ title: 'No URL' });

    expect(resMissing.status).toBe(400);
  });

  it('returns 400 when title exceeds 200 characters', async () => {
    const longTitle = 'a'.repeat(201);
    const res = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'https://example.com', title: longTitle });

    expect(res.status).toBe(400);
  });

  it('accepts title of exactly 200 characters', async () => {
    const title200 = 'a'.repeat(200);
    const res = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'https://example.com', title: title200 });

    expect(res.status).toBe(201);
  });

  it('returns 400 when tags array exceeds 10 items', async () => {
    const tags = Array.from({ length: 11 }, (_, i) => `tag${i}`);
    const res = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'https://example.com', tags });

    expect(res.status).toBe(400);
  });

  it('returns 400 when an individual tag exceeds 50 characters', async () => {
    const longTag = 't'.repeat(51);
    const res = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'https://example.com', tags: [longTag] });

    expect(res.status).toBe(400);
  });

  it('accepts up to 10 tags each up to 50 characters', async () => {
    const tags = Array.from({ length: 10 }, (_, i) => `tag-${i}-${'x'.repeat(40)}`);
    const res = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'https://example.com', tags });

    expect(res.status).toBe(201);
  });
});

import crypto from 'node:crypto';

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags?: string[];
  createdAt: string;
}

export interface CreateBookmarkInput {
  url: string;
  title?: string;
  tags?: string[];
}

export class BookmarkService {
  private readonly bookmarks = new Map<string, Bookmark>();

  create(input: CreateBookmarkInput): Bookmark {
    const id = crypto.randomUUID();
    const bookmark: Bookmark = {
      id,
      url: input.url,
      ...(input.title !== undefined ? { title: input.title } : {}),
      ...(input.tags !== undefined ? { tags: input.tags } : {}),
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(id, bookmark);
    return bookmark;
  }

  findById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  findAll(): Bookmark[] {
    return Array.from(this.bookmarks.values());
  }

  delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  clear(): void {
    this.bookmarks.clear();
  }
}

export const bookmarkService = new BookmarkService();

import { Router, type Request, type Response } from 'express';
import { z } from 'zod';
import {
  bookmarkService,
  BookmarkService,
  type Bookmark,
  type CreateBookmarkInput,
} from '../services/bookmark-service.js';

export type { Bookmark, CreateBookmarkInput };
export { bookmarkService, BookmarkService };

export const createBookmarkSchema = z.object({
  url: z.string().url(),
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export function isCreateBookmarkInput(value: unknown): value is CreateBookmarkInput {
  return createBookmarkSchema.safeParse(value).success;
}

export function clearBookmarks(): void {
  bookmarkService.clear();
}

export const bookmarksRouter = Router();

bookmarksRouter.post(['/', '/api/v1/bookmarks'], (req: Request, res: Response): void => {
  const body: unknown = req.body;
  const parseResult = createBookmarkSchema.safeParse(body);

  if (!parseResult.success) {
    res.status(400).json({
      error: 'Validation failed',
      message: parseResult.error.issues.map((i) => `${i.path.join('.') || 'body'}: ${i.message}`).join('; '),
      issues: parseResult.error.issues,
    });
    return;
  }

  const newBookmark = bookmarkService.create(parseResult.data);

  res.status(201).json(newBookmark);
});

export default bookmarksRouter;

import { describe, it, expect, beforeEach } from 'vitest';
import { BookmarkService } from '../src/services/bookmark-service.js';

describe('BookmarkService', () => {
  let service: BookmarkService;

  beforeEach(() => {
    service = new BookmarkService();
  });

  it('creates and stores a bookmark with a valid UUID', () => {
    const bookmark = service.create({
      url: 'https://example.com',
      title: 'Example',
      tags: ['test'],
    });

    expect(bookmark.id).toBeDefined();
    expect(typeof bookmark.id).toBe('string');
    expect(bookmark.id).toMatch(
      /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i,
    );
    expect(bookmark.url).toBe('https://example.com');
    expect(bookmark.title).toBe('Example');
    expect(bookmark.tags).toEqual(['test']);
    expect(typeof bookmark.createdAt).toBe('string');

    const found = service.findById(bookmark.id);
    expect(found).toEqual(bookmark);
  });

  it('retrieves all stored bookmarks', () => {
    expect(service.findAll()).toEqual([]);

    const b1 = service.create({ url: 'https://example.com/1' });
    const b2 = service.create({ url: 'https://example.com/2' });

    const all = service.findAll();
    expect(all).toHaveLength(2);
    expect(all).toContainEqual(b1);
    expect(all).toContainEqual(b2);
  });

  it('deletes a bookmark by id', () => {
    const b = service.create({ url: 'https://example.com' });
    expect(service.findById(b.id)).toBeDefined();

    const deleted = service.delete(b.id);
    expect(deleted).toBe(true);
    expect(service.findById(b.id)).toBeUndefined();

    const deletedAgain = service.delete(b.id);
    expect(deletedAgain).toBe(false);
  });

  it('clears all bookmarks', () => {
    service.create({ url: 'https://example.com/1' });
    service.create({ url: 'https://example.com/2' });
    expect(service.findAll()).toHaveLength(2);

    service.clear();
    expect(service.findAll()).toHaveLength(0);
  });
});

