import { describe, it, expect } from 'vitest';
import request from 'supertest';
import express, { type Request, type Response, type NextFunction } from 'express';
import { app } from '../src/app.js';
import { errorHandler } from '../src/middleware/error-handler.js';

describe('Error Handling Middleware', () => {
  it('returns 400 when invalid JSON is sent', async () => {
    const res = await request(app)
      .post('/api/v1/bookmarks')
      .set('Content-Type', 'application/json')
      .send('{ "url": "https://example.com", malformed ');

    expect(res.status).toBe(400);
    const body = res.body as Record<string, unknown>;
    expect(body.error).toBe('Invalid JSON');
  });

  it('returns 422 with zod error details for validation errors', async () => {
    const res = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'not-a-url' });

    expect(res.status).toBe(422);
    const body = res.body as Record<string, unknown>;
    expect(body.error).toBe('Validation Error');
    expect(body.details).toBeDefined();
    expect(Array.isArray(body.details)).toBe(true);
    const details = body.details as Array<Record<string, unknown>>;
    expect(details.length).toBeGreaterThan(0);
    expect(details[0].path).toEqual(['url']);
  });

  it('returns 500 with no stack trace when an unexpected error occurs', async () => {
    const testApp = express();
    testApp.use(express.json());

    testApp.get('/crash', (_req: Request, _res: Response): void => {
      throw new Error('Database connection crashed');
    });

    testApp.use(errorHandler);

    const res = await request(testApp).get('/crash');

    expect(res.status).toBe(500);
    const body = res.body as Record<string, unknown>;
    expect(body.error).toBe('Internal Server Error');
    expect(body.message).toBe('An unexpected error occurred');

    // Ensure NO stack trace is leaked in response
    expect(body.stack).toBeUndefined();
    expect(JSON.stringify(body)).not.toContain('stack');
    expect(JSON.stringify(body)).not.toContain('Database connection crashed');
  });

  it('delegates to next if headers are already sent', async () => {
    const testApp = express();

    testApp.get('/stream-error', (_req: Request, res: Response, next: NextFunction): void => {
      res.writeHead(200, { 'Content-Type': 'text/plain' });
      res.write('chunk');
      next(new Error('Stream failure after headers sent'));
    });

    testApp.use(errorHandler);

