import { describe, it, expect } from 'vitest';
import { createBookmarkSchema } from './bookmarks.js';

describe('createBookmarkSchema unit tests', () => {
  it('accepts valid inputs with only url', () => {
    const input = { url: 'https://example.com' };
    const result = createBookmarkSchema.safeParse(input);

    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data.url).toBe(input.url);
      expect(result.data.title).toBeUndefined();
      expect(result.data.tags).toBeUndefined();
    }
  });

  it('accepts valid inputs with full payload', () => {
    const input = {
      url: 'https://example.com/docs',
      title: 'Documentation',
      tags: ['typescript', 'api'],
    };
    const result = createBookmarkSchema.safeParse(input);

    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data.url).toBe(input.url);
      expect(result.data.title).toBe(input.title);
      expect(result.data.tags).toEqual(input.tags);
    }
  });

  it('accepts boundary limits (title of 200 chars, 10 tags each 50 chars)', () => {
    const input = {
      url: 'https://example.com',
      title: 'a'.repeat(200),
      tags: Array.from({ length: 10 }, (_, i) => `${i}-${'b'.repeat(48)}`),
    };
    const result = createBookmarkSchema.safeParse(input);

    expect(result.success).toBe(true);
  });

  it('fails when url is missing', () => {
    const input = { title: 'Missing URL', tags: ['test'] };
    const result = createBookmarkSchema.safeParse(input);

    expect(result.success).toBe(false);
    if (!result.success) {
      const urlIssue = result.error.issues.find((issue) => issue.path.includes('url'));
      expect(urlIssue).toBeDefined();
    }
  });

  it('fails when url is too long (> 2048 characters)', () => {
    const longUrl = `https://example.com/${'a'.repeat(2040)}`;
    expect(longUrl.length).toBeGreaterThan(2048);

    const input = { url: longUrl };
    const result = createBookmarkSchema.safeParse(input);

    expect(result.success).toBe(false);
    if (!result.success) {
      const urlIssue = result.error.issues.find((issue) => issue.path.includes('url'));
      expect(urlIssue).toBeDefined();
    }
  });

  it('fails when too many tags are provided (> 10 tags)', () => {
    const input = {
      url: 'https://example.com',
      tags: Array.from({ length: 11 }, (_, i) => `tag-${i}`),
    };
    const result = createBookmarkSchema.safeParse(input);

    expect(result.success).toBe(false);
    if (!result.success) {
      const tagsIssue = result.error.issues.find((issue) => issue.path.includes('tags'));
      expect(tagsIssue).toBeDefined();
    }
  });

  it('fails when an individual tag is too long (> 50 characters)', () => {
    const input = {
      url: 'https://example.com',
      tags: ['valid-tag', 't'.repeat(51)],
    };
    const result = createBookmarkSchema.safeParse(input);

    expect(result.success).toBe(false);
    if (!result.success) {
      const tagIssue = result.error.issues.find((issue) => issue.path.includes('tags'));
      expect(tagIssue).toBeDefined();
    }
  });

  it('fails when url is not a valid URL format', () => {
    const input = { url: 'not-a-valid-url' };
    const result = createBookmarkSchema.safeParse(input);

    expect(result.success).toBe(false);
    if (!result.success) {
      const urlIssue = result.error.issues.find((issue) => issue.path.includes('url'));
      expect(urlIssue).toBeDefined();
    }
  });

  it('fails when title is too long (> 200 characters)', () => {
    const input = {
      url: 'https://example.com',
      title: 'a'.repeat(201),
    };
    const result = createBookmarkSchema.safeParse(input);

