import crypto from 'node:crypto';

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags?: string[];
  createdAt: string;
}

export interface CreateBookmarkInput {
  url: string;
  title?: string;
  tags?: string[];
}

export class DuplicateBookmarkError extends Error {
  constructor(url: string) {
    super(`Bookmark with URL "${url}" already exists`);
    this.name = 'DuplicateBookmarkError';
  }
}

export class BookmarkService {
  private readonly bookmarks = new Map<string, Bookmark>();

  create(input: CreateBookmarkInput): Bookmark {
    if (this.findByUrl(input.url)) {
      throw new DuplicateBookmarkError(input.url);
    }

    const id = crypto.randomUUID();
    const bookmark: Bookmark = {
      id,
      url: input.url,
      ...(input.title !== undefined ? { title: input.title } : {}),
      ...(input.tags !== undefined ? { tags: input.tags } : {}),
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(id, bookmark);
    return bookmark;
  }

  findById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  findByUrl(url: string): Bookmark | undefined {
    for (const bookmark of this.bookmarks.values()) {
      if (bookmark.url === url) {
        return bookmark;
      }
    }
    return undefined;
  }

  findAll(): Bookmark[] {
    return Array.from(this.bookmarks.values());
  }

  delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  clear(): void {
    this.bookmarks.clear();
  }
}

export const bookmarkService = new BookmarkService();

import type { Request, Response, NextFunction } from 'express';
import { ZodError } from 'zod';
import { DuplicateBookmarkError } from '../services/bookmark-service.js';

export interface JsonSyntaxError extends SyntaxError {
  status?: number;
  statusCode?: number;
  type?: string;
}

export function isJsonSyntaxError(err: unknown): err is JsonSyntaxError {
  if (err instanceof SyntaxError) {
    const candidate = err as unknown as Record<string, unknown>;
    return (
      candidate.status === 400 ||
      candidate.statusCode === 400 ||
      candidate.type === 'entity.parse.failed'
    );
  }
  return false;
}

export function isZodError(err: unknown): err is ZodError {
  return err instanceof ZodError;
}

export function isDuplicateBookmarkError(err: unknown): err is DuplicateBookmarkError {
  return err instanceof DuplicateBookmarkError;
}

export function errorHandler(
  err: unknown,
  _req: Request,
  res: Response,
  next: NextFunction,
): void {
  if (res.headersSent) {
    next(err);
    return;
  }

  if (isJsonSyntaxError(err)) {
    res.status(400).json({
      error: 'Invalid JSON',
      message: 'Malformed JSON in request body',
    });
    return;
  }

  if (isZodError(err)) {
    res.status(422).json({
      error: 'Validation Error',
      message: 'Validation failed',
      details: err.issues,
      issues: err.issues,
    });
    return;
  }

  if (isDuplicateBookmarkError(err)) {
    res.status(409).json({
      error: 'Conflict',
      message: err.message,
    });
    return;
  }

  res.status(500).json({
    error: 'Internal Server Error',
    message: 'An unexpected error occurred',
  });
}

export default errorHandler;

import { describe, it, expect, beforeEach } from 'vitest';
import {
  BookmarkService,
  DuplicateBookmarkError,
} from '../src/services/bookmark-service.js';

describe('BookmarkService', () => {
  let service: BookmarkService;

  beforeEach(() => {
    service = new BookmarkService();
  });

  describe('create', () => {
    it('creates and stores a bookmark with a valid UUID and createdAt timestamp', () => {
      const bookmark = service.create({
        url: 'https://example.com',
        title: 'Example',
        tags: ['web', 'test'],
      });

      expect(bookmark.id).toBeDefined();
      expect(typeof bookmark.id).toBe('string');
      expect(bookmark.id).toMatch(
        /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i,
      );
      expect(bookmark.url).toBe('https://example.com');
      expect(bookmark.title).toBe('Example');
      expect(bookmark.tags).toEqual(['web', 'test']);
      expect(typeof bookmark.createdAt).toBe('string');
      expect(Number.isNaN(Date.parse(bookmark.createdAt))).toBe(false);
    });

    it('creates a bookmark with only url and leaves title and tags undefined', () => {
      const bookmark = service.create({ url: 'https://example.com/minimal' });

      expect(bookmark.url).toBe('https://example.com/minimal');
      expect(bookmark.title).toBeUndefined();
      expect(bookmark.tags).toBeUndefined();
    });
  });

  describe('duplicate detection (same URL)', () => {
    it('throws DuplicateBookmarkError when creating a bookmark with a duplicate URL', () => {
      service.create({ url: 'https://example.com' });

      expect(() => {
        service.create({ url: 'https://example.com' });
      }).toThrow(DuplicateBookmarkError);

      expect(() => {
        service.create({
          url: 'https://example.com',
          title: 'Different title',
          tags: ['different'],
        });
      }).toThrow(/already exists/i);
    });

    it('allows creating bookmarks with distinct URLs', () => {
      const b1 = service.create({ url: 'https://example.com/one' });
      const b2 = service.create({ url: 'https://example.com/two' });

      expect(b1.id).not.toBe(b2.id);
      expect(service.findAll()).toHaveLength(2);
    });

    it('allows re-creating a URL after deleting the original bookmark', () => {
      const b1 = service.create({ url: 'https://example.com/recreate' });
      service.delete(b1.id);

      expect(() => {
        service.create({ url: 'https://example.com/recreate', title: 'New' });
      }).not.toThrow();

      const found = service.findByUrl('https://example.com/recreate');
      expect(found).toBeDefined();
      expect(found?.title).toBe('New');
    });

    it('allows re-creating a URL after clearing all bookmarks', () => {
      service.create({ url: 'https://example.com/cleared' });
      service.clear();

      expect(() => {
        service.create({ url: 'https://example.com/cleared' });
      }).not.toThrow();

      expect(service.findAll()).toHaveLength(1);
    });
  });

  describe('retrieval', () => {
    it('retrieves a bookmark by ID via findById', () => {
      const created = service.create({
        url: 'https://example.com/retrieve',
        title: 'Retrieve Test',
      });

      const retrieved = service.findById(created.id);
      expect(retrieved).toEqual(created);
    });

    it('returns undefined from findById when ID does not exist', () => {
      const retrieved = service.findById('non-existent-uuid');
      expect(retrieved).toBeUndefined();
    });

    it('retrieves a bookmark by URL via findByUrl', () => {
      const created = service.create({
        url: 'https://example.com/by-url',
        title: 'Find by URL',
      });

      const retrieved = service.findByUrl('https://example.com/by-url');
      expect(retrieved).toEqual(created);
    });

    it('returns undefined from findByUrl when URL does not exist', () => {
      const retrieved = service.findByUrl('https://example.com/not-present');
      expect(retrieved).toBeUndefined();
    });

    it('retrieves all stored bookmarks via findAll', () => {
      expect(service.findAll()).toEqual([]);

      const b1 = service.create({ url: 'https://example.com/1' });
      const b2 = service.create({ url: 'https://example.com/2' });

      const all = service.findAll();
      expect(all).toHaveLength(2);
      expect(all).toContainEqual(b1);
      expect(all).toContainEqual(b2);
    });
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import {
  BookmarkService,
  DuplicateBookmarkError,
} from './bookmark-service.js';

describe('BookmarkService unit tests', () => {
  let service: BookmarkService;

  beforeEach(() => {
    service = new BookmarkService();
  });

  describe('create', () => {
    it('creates and stores a bookmark with a valid UUID and createdAt timestamp', () => {
      const bookmark = service.create({
        url: 'https://example.com',
        title: 'Example',
        tags: ['web', 'test'],
      });

      expect(bookmark.id).toBeDefined();
      expect(typeof bookmark.id).toBe('string');
      expect(bookmark.id).toMatch(
        /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i,
      );
      expect(bookmark.url).toBe('https://example.com');
      expect(bookmark.title).toBe('Example');
      expect(bookmark.tags).toEqual(['web', 'test']);
      expect(typeof bookmark.createdAt).toBe('string');
      expect(Number.isNaN(Date.parse(bookmark.createdAt))).toBe(false);
    });

    it('creates a bookmark with only url and leaves title and tags undefined', () => {
      const bookmark = service.create({ url: 'https://example.com/minimal' });

      expect(bookmark.url).toBe('https://example.com/minimal');
      expect(bookmark.title).toBeUndefined();
      expect(bookmark.tags).toBeUndefined();
    });
  });

  describe('duplicate detection (same URL)', () => {
    it('throws DuplicateBookmarkError when creating a bookmark with a duplicate URL', () => {
      service.create({ url: 'https://example.com' });

      expect(() => {
        service.create({ url: 'https://example.com' });
      }).toThrow(DuplicateBookmarkError);

      expect(() => {
        service.create({
          url: 'https://example.com',
          title: 'Different title',
          tags: ['different'],
        });
      }).toThrow(/already exists/i);
    });

    it('allows creating bookmarks with distinct URLs', () => {
      const b1 = service.create({ url: 'https://example.com/one' });
      const b2 = service.create({ url: 'https://example.com/two' });

      expect(b1.id).not.toBe(b2.id);
      expect(service.findAll()).toHaveLength(2);
    });

    it('allows re-creating a URL after deleting the original bookmark', () => {
      const b1 = service.create({ url: 'https://example.com/recreate' });
      service.delete(b1.id);

      expect(() => {
        service.create({ url: 'https://example.com/recreate', title: 'New' });
      }).not.toThrow();

      const found = service.findByUrl('https://example.com/recreate');
      expect(found).toBeDefined();
      expect(found?.title).toBe('New');
    });

    it('allows re-creating a URL after clearing all bookmarks', () => {
      service.create({ url: 'https://example.com/cleared' });
      service.clear();

      expect(() => {
        service.create({ url: 'https://example.com/cleared' });
      }).not.toThrow();

      expect(service.findAll()).toHaveLength(1);
    });
  });

  describe('retrieval', () => {
    it('retrieves a bookmark by ID via findById', () => {
      const created = service.create({
        url: 'https://example.com/retrieve',
        title: 'Retrieve Test',
      });

      const retrieved = service.findById(created.id);
      expect(retrieved).toEqual(created);
    });

    it('returns undefined from findById when ID does not exist', () => {
      const retrieved = service.findById('non-existent-uuid');
      expect(retrieved).toBeUndefined();
    });

    it('retrieves a bookmark by URL via findByUrl', () => {
      const created = service.create({
        url: 'https://example.com/by-url',
        title: 'Find by URL',
      });

      const retrieved = service.findByUrl('https://example.com/by-url');
      expect(retrieved).toEqual(created);
    });

    it('returns undefined from findByUrl when URL does not exist', () => {
      const retrieved = service.findByUrl('https://example.com/not-present');
      expect(retrieved).toBeUndefined();
    });

    it('retrieves all stored bookmarks via findAll', () => {
      expect(service.findAll()).toEqual([]);

      const b1 = service.create({ url: 'https://example.com/1' });
      const b2 = service.create({ url: 'https://example.com/2' });

      const all = service.findAll();
      expect(all).toHaveLength(2);
      expect(all).toContainEqual(b1);
      expect(all).toContainEqual(b2);
    });
  });
});

