import type { Request, Response, NextFunction } from 'express';
import { ZodError } from 'zod';
import { DuplicateBookmarkError } from '../services/bookmark-service.js';

export interface JsonSyntaxError extends SyntaxError {
  status?: number;
  statusCode?: number;
  type?: string;
}

export function isJsonSyntaxError(err: unknown): err is JsonSyntaxError {
  if (err instanceof SyntaxError) {
    const candidate = err as unknown as Record<string, unknown>;
    return (
      candidate.status === 400 ||
      candidate.statusCode === 400 ||
      candidate.type === 'entity.parse.failed'
    );
  }
  return false;
}

export function isZodError(err: unknown): err is ZodError {
  return err instanceof ZodError;
}

export function isDuplicateBookmarkError(err: unknown): err is DuplicateBookmarkError {
  return err instanceof DuplicateBookmarkError;
}

export function errorHandler(
  err: unknown,
  _req: Request,
  res: Response,
  next: NextFunction,
): void {
  if (res.headersSent) {
    next(err);
    return;
  }

  if (isJsonSyntaxError(err)) {
    res.status(400).json({
      error: 'Invalid JSON',
      message: 'Malformed JSON in request body',
    });
    return;
  }

  if (isZodError(err)) {
    res.status(422).json({
      error: 'Validation Error',
      message: 'Validation failed',
      details: err.issues,
      issues: err.issues,
    });
    return;
  }

  if (isDuplicateBookmarkError(err)) {
    res.status(409).json({
      error: 'Conflict',
      message: err.message,
    });
    return;
  }

  res.status(500).json({
    error: 'Internal Server Error',
    message: 'An unexpected error occurred',
  });
}

export default errorHandler;

