import { describe, it, expect, beforeEach } from 'vitest';
import request from 'supertest';
import express from 'express';
import { app } from '../src/app.js';
import {
  clearBookmarks,
  createBookmarksRouter,
  bookmarkService,
} from '../src/routes/bookmarks.js';
import { BookmarkService } from '../src/services/bookmark-service.js';

describe('POST /api/v1/bookmarks', () => {
  beforeEach(() => {
    clearBookmarks();
  });

  it('creates a bookmark with only url and returns 201 with generated id and createdAt', async () => {
    const res = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'https://example.com' });

    expect(res.status).toBe(201);
    const body: unknown = res.body;
    expect(body).toBeTypeOf('object');
    expect(body).not.toBeNull();
    const record = body as Record<string, unknown>;

    expect(record.id).toBeTypeOf('string');
    expect(record.id).toMatch(
      /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i,
    );
    expect(record.url).toBe('https://example.com');
    expect(record.createdAt).toBeTypeOf('string');
    expect(Number.isNaN(Date.parse(record.createdAt as string))).toBe(false);

    const stored = bookmarkService.findById(record.id as string);
    expect(stored).toBeDefined();
    expect(stored?.url).toBe('https://example.com');
  });

  it('creates a bookmark with url, title, and tags and returns 201 with all fields', async () => {
    const payload = {
      url: 'https://example.com/docs',
      title: 'Documentation',
      tags: ['typescript', 'docs'],
    };

    const res = await request(app)
      .post('/api/v1/bookmarks')
      .send(payload);

    expect(res.status).toBe(201);
    const body: unknown = res.body;
    const record = body as Record<string, unknown>;
    expect(record.url).toBe(payload.url);
    expect(record.title).toBe(payload.title);
    expect(record.tags).toEqual(payload.tags);
    expect(record.id).toBeTypeOf('string');
    expect(record.createdAt).toBeTypeOf('string');

    const stored = bookmarkService.findById(record.id as string);
    expect(stored).toEqual({
      id: record.id,
      url: payload.url,
      title: payload.title,
      tags: payload.tags,
      createdAt: record.createdAt,
    });
  });

  it('supports injecting a custom BookmarkService instance into createBookmarksRouter', async () => {
    const customService = new BookmarkService();
    const customApp = express();
    customApp.use(express.json());
    customApp.use('/api/v1/bookmarks', createBookmarksRouter(customService));

    const res = await request(customApp)
      .post('/api/v1/bookmarks')
      .send({ url: 'https://custom.example.com', title: 'Custom' });

    expect(res.status).toBe(201);
    const record = res.body as Record<string, unknown>;
    const stored = customService.findById(record.id as string);
    expect(stored).toBeDefined();
    expect(stored?.title).toBe('Custom');
    expect(bookmarkService.findById(record.id as string)).toBeUndefined();
  });

  it('returns 422 with zod error details when url is invalid or missing', async () => {
    const resInvalid = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'not-a-valid-url' });

    expect(resInvalid.status).toBe(422);
    const bodyInvalid = resInvalid.body as Record<string, unknown>;
    expect(bodyInvalid.details).toBeDefined();
    expect(Array.isArray(bodyInvalid.details)).toBe(true);

    const resEmpty = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: '' });

    expect(resEmpty.status).toBe(422);

    const resMissing = await request(app)
      .post('/api/v1/bookmarks')
      .send({ title: 'No URL' });

    expect(resMissing.status).toBe(422);
  });

  it('returns 422 when title exceeds 200 characters', async () => {
    const longTitle = 'a'.repeat(201);
    const res = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'https://example.com', title: longTitle });

    expect(res.status).toBe(422);
    const body = res.body as Record<string, unknown>;
    expect(body.details).toBeDefined();
  });

  it('accepts title of exactly 200 characters', async () => {
    const title200 = 'a'.repeat(200);
    const res = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'https://example.com', title: title200 });

    expect(res.status).toBe(201);
  });

  it('returns 422 when tags array exceeds 10 items', async () => {
    const tags = Array.from({ length: 11 }, (_, i) => `tag${i}`);
    const res = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'https://example.com', tags });

    expect(res.status).toBe(422);
    const body = res.body as Record<string, unknown>;
    expect(body.details).toBeDefined();
  });

  it('returns 422 when an individual tag exceeds 50 characters', async () => {
    const longTag = 't'.repeat(51);
    const res = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'https://example.com', tags: [longTag] });

    expect(res.status).toBe(422);
    const body = res.body as Record<string, unknown>;
    expect(body.details).toBeDefined();
  });

  it('accepts up to 10 tags each up to 50 characters', async () => {
    const tags = Array.from({ length: 10 }, (_, i) => `tag-${i}-${'x'.repeat(40)}`);
    const res = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'https://example.com', tags });

    expect(res.status).toBe(201);
  });
});

