import { Router, type Request, type Response, type NextFunction } from 'express';
import { z } from 'zod';
import {
  bookmarkService,
  BookmarkService,
  type Bookmark,
  type CreateBookmarkInput,
} from '../services/bookmark-service.js';

export type { Bookmark, CreateBookmarkInput };
export { bookmarkService, BookmarkService };

export const createBookmarkSchema = z.object({
  url: z.string().url().max(2048),
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export function isCreateBookmarkInput(value: unknown): value is CreateBookmarkInput {
  return createBookmarkSchema.safeParse(value).success;
}

export function clearBookmarks(): void {
  bookmarkService.clear();
}

export function createBookmarksRouter(service: BookmarkService = bookmarkService): Router {
  const router = Router();

  router.get(['/', '/api/v1/bookmarks'], (_req: Request, res: Response): void => {
    const allBookmarks = service.findAll();
    res.status(200).json(allBookmarks);
  });

  router.get(['/:id', '/api/v1/bookmarks/:id'], (req: Request<{ id: string }>, res: Response): void => {
    const rawId = req.params.id;
    const id = typeof rawId === 'string' ? rawId : Array.isArray(rawId) ? rawId[0] : '';
    const bookmark = service.findById(id);

    if (!bookmark) {
      res.status(404).json({
        error: 'Not Found',
        message: `Bookmark with id "${id}" not found`,
      });
      return;
    }

    res.status(200).json(bookmark);
  });

  router.post(['/', '/api/v1/bookmarks'], (req: Request, res: Response, next: NextFunction): void => {
    try {
      const body: unknown = req.body;
      const parseResult = createBookmarkSchema.safeParse(body);

      if (!parseResult.success) {
        next(parseResult.error);
        return;
      }

      const newBookmark = service.create(parseResult.data);

      res.status(201).json(newBookmark);
    } catch (err: unknown) {
      next(err);
    }
  });

  router.delete(['/:id', '/api/v1/bookmarks/:id'], (req: Request<{ id: string }>, res: Response): void => {
    const rawId = req.params.id;
    const id = typeof rawId === 'string' ? rawId : Array.isArray(rawId) ? rawId[0] : '';

    if (!id) {
      res.status(404).json({
        error: 'Not Found',
        message: 'Bookmark not found',
      });
      return;
    }

    const deleted = service.delete(id);
    if (!deleted) {
      res.status(404).json({
        error: 'Not Found',
        message: `Bookmark with id "${id}" not found`,
      });
      return;
    }

    res.status(204).send();
  });

  return router;
}

export const bookmarksRouter = createBookmarksRouter(bookmarkService);

export default bookmarksRouter;

