I have implemented pagination for the `GET /api/v1/bookmarks` endpoint:

### Changes Implemented
1. **Types & Service (`src/services/bookmark-service.ts`)**:
   - Added `PaginationMeta` and `PaginatedResult<T>` interfaces:
     ```typescript
     export interface PaginationMeta {
       page: number;
       limit: number;
       total: number;
       totalPages: number;
     }

     export interface PaginatedResult<T> {
       data: T[];
       pagination: PaginationMeta;
     }
     ```
   - Added `getPaginated(page: number, limit: number): PaginatedResult<Bookmark>` to `BookmarkService`, calculating offsets, slicing the sorted data, and computing `totalPages`.

2. **Route Handler (`src/routes/bookmarks.ts`)**:
   - Added `parsePaginationParams(query: Record<string, unknown>)` supporting defaults (`page = 1`, `limit = 20`) with strict boundaries (page ≥ 1, 1 ≤ limit ≤ 100).
   - Updated `GET /api/v1/bookmarks` to accept query params `?page=1&limit=20` and return `{ data: Bookmark[], pagination: { page, limit, total, totalPages } }`.

3. **Integration & Unit Testing**:
   - Updated unit and integration tests to verify the `{ data, pagination }` structure, default pagination, and custom page/limit parameters.
   - All 55 tests pass (`npm test`).
   - `npm run typecheck` (`tsc --noEmit`) passes with zero errors under `strict: true`. No `any` types used.

import crypto from 'node:crypto';

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags?: string[];
  createdAt: string;
}

export interface CreateBookmarkInput {
  url: string;
  title?: string;
  tags?: string[];
}

export interface PaginationMeta {
  page: number;
  limit: number;
  total: number;
  totalPages: number;
}

export interface PaginatedResult<T> {
  data: T[];
  pagination: PaginationMeta;
}

export class DuplicateBookmarkError extends Error {
  constructor(url: string) {
    super(`Bookmark with URL "${url}" already exists`);
    this.name = 'DuplicateBookmarkError';
  }
}

export class BookmarkService {
  private readonly bookmarks = new Map<string, Bookmark>();

  create(input: CreateBookmarkInput): Bookmark {
    if (this.findByUrl(input.url)) {
      throw new DuplicateBookmarkError(input.url);
    }

    const id = crypto.randomUUID();
    const bookmark: Bookmark = {
      id,
      url: input.url,
      ...(input.title !== undefined ? { title: input.title } : {}),
      ...(input.tags !== undefined ? { tags: input.tags } : {}),
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(id, bookmark);
    return bookmark;
  }

  findById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  findByUrl(url: string): Bookmark | undefined {
    for (const bookmark of this.bookmarks.values()) {
      if (bookmark.url === url) {
        return bookmark;
      }
    }
    return undefined;
  }

  findAll(): Bookmark[] {
    return Array.from(this.bookmarks.values()).sort(
      (a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt),
    );
  }

  getPaginated(page: number, limit: number): PaginatedResult<Bookmark> {
    const all = this.findAll();
    const total = all.length;
    const totalPages = Math.ceil(total / limit);
    const offset = (page - 1) * limit;
    const data = all.slice(offset, offset + limit);

    return {
      data,
      pagination: {
        page,
        limit,
        total,
        totalPages,
      },
    };
  }

  delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  clear(): void {
    this.bookmarks.clear();
  }
}

export const bookmarkService = new BookmarkService();

