import { Router, type Request, type Response, type NextFunction } from 'express';
import { z } from 'zod';
import {
  bookmarkService,
  BookmarkService,
  type Bookmark,
  type CreateBookmarkInput,
  type UpdateBookmarkInput,
  type PaginationMeta,
  type PaginatedResult,
} from '../services/bookmark-service.js';

export type { Bookmark, CreateBookmarkInput, UpdateBookmarkInput, PaginationMeta, PaginatedResult };
export { bookmarkService, BookmarkService };

export const createBookmarkSchema = z.object({
  url: z.string().url().max(2048),
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type CreateBookmarkSchemaType = z.infer<typeof createBookmarkSchema>;

export const updateBookmarkSchema = z.object({
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type UpdateBookmarkSchemaType = z.infer<typeof updateBookmarkSchema>;

export function isCreateBookmarkInput(value: unknown): value is CreateBookmarkInput {
  return createBookmarkSchema.safeParse(value).success;
}

export function clearBookmarks(): void {
  bookmarkService.clear();
}

function getQueryString(value: unknown): string | undefined {
  if (typeof value === 'string') {
    return value;
  }
  if (Array.isArray(value) && typeof value[0] === 'string') {
    return value[0];
  }
  return undefined;
}

export function parsePaginationParams(query: Record<string, unknown>): { page: number; limit: number } {
  let page = 1;
  let limit = 20;

  const rawPage = getQueryString(query.page);
  if (rawPage !== undefined) {
    const parsed = parseInt(rawPage, 10);
    if (!Number.isNaN(parsed)) {
      page = Math.max(1, parsed);
    }
  }

  const rawLimit = getQueryString(query.limit);
  if (rawLimit !== undefined) {
    const parsed = parseInt(rawLimit, 10);
    if (!Number.isNaN(parsed)) {
      limit = Math.min(100, Math.max(1, parsed));
    }
  }

  return { page, limit };
}

export function createBookmarksRouter(service: BookmarkService = bookmarkService): Router {
  const router = Router();

  router.get(['/', '/api/v1/bookmarks'], (req: Request, res: Response): void => {
    const query = req.query as Record<string, unknown>;
    const { page, limit } = parsePaginationParams(query);
    const paginatedResult = service.getPaginated(page, limit);
    res.status(200).json(paginatedResult);
  });

  router.get(['/:id', '/api/v1/bookmarks/:id'], (req: Request<{ id: string }>, res: Response): void => {
    const rawId = req.params.id;
    const id = typeof rawId === 'string' ? rawId : Array.isArray(rawId) ? rawId[0] : '';
    const bookmark = service.findById(id);

    if (!bookmark) {
      res.status(404).json({
        error: 'Not Found',
        message: `Bookmark with id "${id}" not found`,
      });
      return;
    }

    res.status(200).json(bookmark);
  });

  router.post(['/', '/api/v1/bookmarks'], (req: Request, res: Response, next: NextFunction): void => {
    try {
      const body: unknown = req.body;
      const parseResult = createBookmarkSchema.safeParse(body);

      if (!parseResult.success) {
        next(parseResult.error);
        return;
      }

      const newBookmark = service.create(parseResult.data);

      res.status(201).json(newBookmark);
    } catch (err: unknown) {
      next(err);
    }
  });

  router.patch(['/:id', '/api/v1/bookmarks/:id'], (req: Request<{ id: string }>, res: Response, next: NextFunction): void => {
    const rawId = req.params.id;
    const id = typeof rawId === 'string' ? rawId : Array.isArray(rawId) ? rawId[0] : '';

    if (!id) {
      res.status(404).json({
        error: 'Not Found',
        message: 'Bookmark not found',
      });
      return;
    }

    const body: unknown = req.body;
    if (typeof body === 'object' && body !== null && 'url' in body && (body as Record<string, unknown>).url !== undefined) {
      res.status(400).json({
        error: 'URL is immutable and cannot be updated',
      });
      return;
    }

    const parseResult = updateBookmarkSchema.safeParse(body);
    if (!parseResult.success) {
      next(parseResult.error);
      return;
    }

    const updated = service.update(id, parseResult.data);
    if (!updated) {
      res.status(404).json({
        error: 'Not Found',
        message: `Bookmark with id "${id}" not found`,
      });
      return;
    }

    res.status(200).json(updated);
  });

  router.delete(['/:id', '/api/v1/bookmarks/:id'], (req: Request<{ id: string }>, res: Response): void => {
    const rawId = req.params.id;
    const id = typeof rawId === 'string' ? rawId : Array.isArray(rawId) ? rawId[0] : '';

    if (!id) {
      res.status(404).json({
        error: 'Not Found',
        message: 'Bookmark not found',
      });
      return;
    }

    const deleted = service.delete(id);
    if (!deleted) {
      res.status(404).json({
        error: 'Not Found',
        message: `Bookmark with id "${id}" not found`,
      });
      return;
    }

    res.status(204).send();
  });

  return router;
}

export const bookmarksRouter = createBookmarksRouter(bookmarkService);

export default bookmarksRouter;

