import crypto from 'node:crypto';

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags?: string[];
  createdAt: string;
}

export interface CreateBookmarkInput {
  url: string;
  title?: string;
  tags?: string[];
}

export interface UpdateBookmarkInput {
  title?: string;
  tags?: string[];
}

export interface PaginationMeta {
  page: number;
  limit: number;
  total: number;
  totalPages: number;
}

export interface PaginatedResult<T> {
  data: T[];
  pagination: PaginationMeta;
}

export class DuplicateBookmarkError extends Error {
  constructor(url: string) {
    super(`Bookmark with URL "${url}" already exists`);
    this.name = 'DuplicateBookmarkError';
  }
}

export class BookmarkService {
  private readonly bookmarks = new Map<string, Bookmark>();

  create(input: CreateBookmarkInput): Bookmark {
    if (this.findByUrl(input.url)) {
      throw new DuplicateBookmarkError(input.url);
    }

    const id = crypto.randomUUID();
    const bookmark: Bookmark = {
      id,
      url: input.url,
      ...(input.title !== undefined ? { title: input.title } : {}),
      ...(input.tags !== undefined ? { tags: input.tags } : {}),
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(id, bookmark);
    return bookmark;
  }

  findById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  getById(id: string): Bookmark | undefined {
    return this.findById(id);
  }

  findByUrl(url: string): Bookmark | undefined {
    for (const bookmark of this.bookmarks.values()) {
      if (bookmark.url === url) {
        return bookmark;
      }
    }
    return undefined;
  }

  findAll(): Bookmark[] {
    return Array.from(this.bookmarks.values()).sort(
      (a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt),
    );
  }

  getPaginated(page: number, limit: number): PaginatedResult<Bookmark> {
    const all = this.findAll();
    const total = all.length;
    const totalPages = Math.ceil(total / limit);
    const offset = (page - 1) * limit;
    const data = all.slice(offset, offset + limit);

    return {
      data,
      pagination: {
        page,
        limit,
        total,
        totalPages,
      },
    };
  }

  update(id: string, data: UpdateBookmarkInput): Bookmark | undefined {
    const existing = this.bookmarks.get(id);
    if (!existing) {
      return undefined;
    }

    const updated: Bookmark = {
      ...existing,
      title: data.title !== undefined ? data.title : existing.title,
      tags: data.tags !== undefined ? [...data.tags] : existing.tags,
    };

    this.bookmarks.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  clear(): void {
    this.bookmarks.clear();
  }
}

export const bookmarkService = new BookmarkService();

