\n    expect(log.status).toBe(200);\n    expect(typeof log.duration_ms).toBe('number');\n    expect(log.duration_ms).toBeGreaterThanOrEqual(0);\n\n    consoleSpy.mockRestore();\n  });\n\n  it('logs during actual HTTP requests through Express app', async () => {\n    const consoleSpy = vi.spyOn(console, 'log').mockImplementation(() => {});\n\n    const response = await request(app).get('/health');\n    expect(response.status).toBe(200);\n\n    expect(consoleSpy).toHaveBeenCalled();\n    const lastCall = consoleSpy.mock.calls[consoleSpy.mock.calls.length - 1]?.[0];\n    expect(typeof lastCall).toBe('string');\n\n    const log = JSON.parse(lastCall as string) as RequestLog;\n    expect(log.method).toBe('GET');\n    expect(log.path).toBe('/health');\n    expect(log.status).toBe(200);\n    expect(typeof log.duration_ms).toBe('number');\n    expect(log.duration_ms).toBeGreaterThanOrEqual(0);\n\n    consoleSpy.mockRestore();\n  });\n});\n"},"thoughtSignature":""},{"type":"text","text":""}],"api":"antigravity-api","provider":"antigravity","model":"gemini-3.8-flash","usage":{"input":5500,"output":832,"cacheRead":41619,"cacheWrite":0,"totalTokens":47951,"cost":{"input":0.00055,"output":0.0003328,"cacheRead":0.0010404750000000001,"cacheWrite":0,"total":0.0019232750000000001},"reasoning":168},"stopReason":"toolUse","timestamp":1789104236570,"rawStopReason":"STOP"}}
