}

export interface PaginatedResult<T> {
  data: T[];
  pagination: PaginationMeta;
}

export class DuplicateBookmarkError extends Error {
  constructor(url: string) {
    super(`Bookmark with URL "${url}" already exists`);
    this.name = 'DuplicateBookmarkError';
  }
}

export class BookmarkService {
  private readonly bookmarks = new Map<string, Bookmark>();

  /**
   * Creates and stores a new bookmark.
   *
   * @param input - The bookmark creation payload containing url, optional title, and optional tags.
   * @returns The newly created bookmark with generated ID and ISO createdAt timestamp.
   * @throws {DuplicateBookmarkError} If a bookmark with the specified URL already exists.
   *
   * @example
   * ```ts
   * const bookmark = bookmarkService.create({
   *   url: 'https://example.com',
   *   title: 'Example Domain',
   *   tags: ['example', 'web'],
   * });
   * console.log(bookmark.id);
   * ```
   */
  create(input: CreateBookmarkInput): Bookmark {
    if (this.findByUrl(input.url)) {
      throw new DuplicateBookmarkError(input.url);
    }

    const id = crypto.randomUUID();
    const bookmark: Bookmark = {
      id,
      url: input.url,
      ...(input.title !== undefined ? { title: input.title } : {}),
      ...(input.tags !== undefined ? { tags: input.tags } : {}),
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(id, bookmark);
    return bookmark;
  }

  /**
   * Retrieves a bookmark by its unique identifier.
   *
   * @param id - The unique identifier of the bookmark.
   * @returns The bookmark if found, or undefined if no matching bookmark exists.
   *
   * @example
   * ```ts
   * const bookmark = bookmarkService.findById('123e4567-e89b-12d3-a456-426614174000');
   * if (bookmark) {
   *   console.log(bookmark.url);
   * }
   * ```
   */
  findById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  /**
   * Alias for `findById`. Retrieves a bookmark by its unique identifier.
   *
   * @param id - The unique identifier of the bookmark.
   * @returns The bookmark if found, or undefined if no matching bookmark exists.
   *
   * @example
   * ```ts
   * const bookmark = bookmarkService.getById('123e4567-e89b-12d3-a456-426614174000');
   * if (bookmark) {
   *   console.log(bookmark.title);
   * }
   * ```
   */
  getById(id: string): Bookmark | undefined {
    return this.findById(id);
  }

  /**
   * Retrieves a bookmark by its unique URL.
   *
   * @param url - The exact URL of the bookmark to look up.
   * @returns The bookmark if found, or undefined if no bookmark matches the URL.
   *
   * @example
   * ```ts
   * const existing = bookmarkService.findByUrl('https://example.com');
   * if (existing) {
   *   console.log('Already bookmarked');
   * }
   * ```
   */
  findByUrl(url: string): Bookmark | undefined {
    for (const bookmark of this.bookmarks.values()) {
      if (bookmark.url === url) {
        return bookmark;
      }
    }
    return undefined;
  }

  /**
   * Retrieves all bookmarks sorted by creation date descending (newest first).
   *
   * @returns An array of all stored bookmarks sorted by createdAt descending.
   *
   * @example
   * ```ts
   * const bookmarks = bookmarkService.findAll();
   * console.log(`Total bookmarks: ${bookmarks.length}`);
   * ```
   */
  findAll(): Bookmark[] {
    return Array.from(this.bookmarks.values()).sort(
      (a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt),
    );
  }

  /**
   * Retrieves a paginated list of bookmarks sorted by creation date descending.
   *
   * @param page - 1-based page number.
   * @param limit - Maximum number of items per page.
   * @returns A paginated result containing the page's bookmarks and pagination metadata.
   *
   * @example
   * ```ts
   * const result = bookmarkService.getPaginated(1, 10);
   * console.log(result.data);
   * console.log(result.pagination.totalPages);
   * ```
   */
  getPaginated(page: number, limit: number): PaginatedResult<Bookmark> {
    const all = this.findAll();
    const total = all.length;
    const totalPages = Math.ceil(total / limit);
    const offset = (page - 1) * limit;
    const data = all.slice(offset, offset + limit);

    return {
      data,
      pagination: {
        page,
        limit,
        total,
        totalPages,
      },
    };
  }

  /**
   * Updates the title and/or tags of an existing bookmark. URL cannot be changed.
   *
   * @param id - The unique identifier of the bookmark to update.
   * @param data - The update payload containing optional new title and/or tags.
   * @returns The updated bookmark if found, or undefined if the bookmark does not exist.
   *
   * @example
   * ```ts
   * const updated = bookmarkService.update('123e4567-e89b-12d3-a456-426614174000', {
   *   title: 'New Title',
   *   tags: ['updated-tag'],
   * });
   * ```
   */
  update(id: string, data: UpdateBookmarkInput): Bookmark | undefined {
    const existing = this.bookmarks.get(id);
    if (!existing) {
      return undefined;
    }

    const updated: Bookmark = {
      ...existing,
      title: data.title !== undefined ? data.title : existing.title,
      tags: data.tags !== undefined ? [...data.tags] : existing.tags,
    };

    this.bookmarks.set(id, updated);
    return updated;
  }

  /**
   * Searches bookmarks by title (case-insensitive substring) and tags (exact match).
   *
   * @param query - The search query term.
   * @returns An array of matching bookmarks sorted by createdAt descending.
   *
   * @example
   * ```ts
   * const matches = bookmarkService.search('typescript');
   * matches.forEach((b) => console.log(b.title));
   * ```
   */
  search(query: string): Bookmark[] {
    const trimmed = query.trim();
    if (!trimmed) {
      return [];
    }
    const lower = trimmed.toLowerCase();
    return this.findAll().filter((bookmark) => {
      const titleMatch =
        bookmark.title !== undefined &&
        bookmark.title.toLowerCase().includes(lower);
      const tagMatch =
        bookmark.tags !== undefined &&
        bookmark.tags.some(
          (tag) => tag.toLowerCase() === lower || tag === trimmed,
        );
      return titleMatch || tagMatch;
    });
  }

  /**
   * Deletes a bookmark by its unique identifier.
   *
   * @param id - The unique identifier of the bookmark to delete.
   * @returns True if the bookmark was found and removed, false otherwise.
   *
   * @example
   * ```ts
   * const deleted = bookmarkService.delete('123e4567-e89b-12d3-a456-426614174000');
   * if (deleted) {
   *   console.log('Bookmark deleted');
   * }
   * ```
   */
  delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  /**
   * Removes all bookmarks from memory.
   *
   * @returns Void.
   *
   * @example
   * ```ts
   * bookmarkService.clear();
   * console.log(bookmarkService.findAll().length); // 0
   * ```
   */
  clear(): void {
    this.bookmarks.clear();
  }
}

export const bookmarkService = new BookmarkService();

import { Router, type Request, type Response, type NextFunction } from 'express';
import { z } from 'zod';
import {
  bookmarkService,
  BookmarkService,
  type Bookmark,
  type CreateBookmarkInput,
  type UpdateBookmarkInput,
  type PaginationMeta,
  type PaginatedResult,
} from '../services/bookmark-service.js';

export type { Bookmark, CreateBookmarkInput, UpdateBookmarkInput, PaginationMeta, PaginatedResult };
export { bookmarkService, BookmarkService };

export const createBookmarkSchema = z.object({
  url: z.string().url().max(2048),
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type CreateBookmarkSchemaType = z.infer<typeof createBookmarkSchema>;

export const updateBookmarkSchema = z.object({
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type UpdateBookmarkSchemaType = z.infer<typeof updateBookmarkSchema>;

/**
 * Type guard to check if an unknown value conforms to CreateBookmarkInput.
 *
 * @param value - Value to check.
 * @returns True if value satisfies createBookmarkSchema.
 *
 * @example
 * ```ts
 * if (isCreateBookmarkInput(body)) {
 *   bookmarkService.create(body);
 * }
 * ```
 */
export function isCreateBookmarkInput(value: unknown): value is CreateBookmarkInput {
  return createBookmarkSchema.safeParse(value).success;
}

/**
 * Convenience helper to clear all bookmarks from the default service instance.
 *
 * @returns Void.
 *
 * @example
 * ```ts
 * clearBookmarks();
 * ```
 */
export function clearBookmarks(): void {
  bookmarkService.clear();
}

/**
 * Extracts a single string value from an unknown query parameter value.
 *
 * @param value - The raw query parameter value.
 * @returns The string representation if valid, otherwise undefined.
 *
 * @example
 * ```ts
 * const param = getQueryString(req.query.q);
 * ```
 */
function getQueryString(value: unknown): string | undefined {
  if (typeof value === 'string') {
    return value;
  }
  if (Array.isArray(value) && typeof value[0] === 'string') {
    return value[0];
  }
  return undefined;
}

/**
 * Parses and bounds pagination query parameters (page and limit).
 *
 * @param query - Request query object.
 * @returns An object with validated `page` (minimum 1) and `limit` (clamped between 1 and 100).
 *
 * @example
 * ```ts
 * const { page, limit } = parsePaginationParams(req.query);
 * ```
 */
export function parsePaginationParams(query: Record<string, unknown>): { page: number; limit: number } {
  let page = 1;
  let limit = 20;

  const rawPage = getQueryString(query.page);
  if (rawPage !== undefined) {
    const parsed = parseInt(rawPage, 10);
    if (!Number.isNaN(parsed)) {
      page = Math.max(1, parsed);
    }
  }

  const rawLimit = getQueryString(query.limit);
  if (rawLimit !== undefined) {
    const parsed = parseInt(rawLimit, 10);
    if (!Number.isNaN(parsed)) {
      limit = Math.min(100, Math.max(1, parsed));
    }
  }

  return { page, limit };
}

/**
 * Creates and configures an Express Router for bookmark CRUD and search endpoints.
 *
 * @param service - The BookmarkService instance to bind to route handlers (defaults to singleton).
 * @returns Configured Express Router.
 *
 * @example
 * ```ts
 * const router = createBookmarksRouter(new BookmarkService());
 * app.use('/api/v1/bookmarks', router);
 * ```
 */
export function createBookmarksRouter(service: BookmarkService = bookmarkService): Router {
  const router = Router();

  /**
   * Handles GET /api/v1/bookmarks - Lists bookmarks with pagination support.
   *
   * @param req - Express request with optional `page` and `limit` query parameters.
   * @param res - Express response sending paginated bookmark results.
   * @returns Void.
   *
   * @example
   * ```ts
   * // GET /api/v1/bookmarks?page=1&limit=20
   * router.get('/', listBookmarksHandler);
   * ```
   */
  function listBookmarksHandler(req: Request, res: Response): void {
    const query = req.query as Record<string, unknown>;
    const { page, limit } = parsePaginationParams(query);
    const paginatedResult = service.getPaginated(page, limit);
    res.status(200).json(paginatedResult);
  }

  /**
   * Handles GET /api/v1/bookmarks/search - Searches bookmarks by title (case-insensitive substring) or tags (exact match).
   *
   * @param req - Express request with required non-empty `q` query parameter.
   * @param res - Express response sending matching bookmarks or 400 error.
   * @returns Void.
   *
   * @example
   * ```ts
   * // GET /api/v1/bookmarks/search?q=typescript
   * router.get('/search', searchBookmarksHandler);
   * ```
   */
  function searchBookmarksHandler(req: Request, res: Response): void {
    const rawQ = getQueryString(req.query.q);
    if (rawQ === undefined || rawQ.trim() === '') {
      res.status(400).json({ error: 'Search query parameter "q" is required and cannot be empty' });
      return;
    }

    const results = service.search(rawQ);
    res.status(200).json(results);
  }

  /**
   * Handles GET /api/v1/bookmarks/:id - Retrieves a single bookmark by its ID.
   *
   * @param req - Express request containing the bookmark ID parameter.
   * @param res - Express response sending the bookmark or 404 error.
   * @returns Void.
   *
   * @example
   * ```ts
   * // GET /api/v1/bookmarks/123e4567-e89b-12d3-a456-426614174000
   * router.get('/:id', getBookmarkByIdHandler);
   * ```
   */
  function getBookmarkByIdHandler(req: Request<{ id: string }>, res: Response): void {
    const rawId = req.params.id;
    const id = typeof rawId === 'string' ? rawId : Array.isArray(rawId) ? rawId[0] : '';
    const bookmark = service.findById(id);

    if (!bookmark) {
      res.status(404).json({
        error: 'Not Found',
        message: `Bookmark with id "${id}" not found`,
      });
      return;
    }

    res.status(200).json(bookmark);
  }

  /**
   * Handles POST /api/v1/bookmarks - Creates a new bookmark.
   *
   * @param req - Express request containing the bookmark creation payload in body.
   * @param res - Express response sending the created bookmark with 201 or error status.
   * @param next - Express next middleware function for error delegation.
   * @returns Void.
   *
   * @example
   * ```ts
   * // POST /api/v1/bookmarks
   * // Body: { "url": "https://example.com", "title": "Example", "tags": ["web"] }
   * router.post('/', createBookmarkHandler);
   * ```
   */
  function createBookmarkHandler(req: Request, res: Response, next: NextFunction): void {
    try {
      const body: unknown = req.body;
      const parseResult = createBookmarkSchema.safeParse(body);

      if (!parseResult.success) {
        next(parseResult.error);
        return;
      }

      const newBookmark = service.create(parseResult.data);

      res.status(201).json(newBookmark);
    } catch (err: unknown) {
      next(err);
    }
  }

  /**
   * Handles PATCH /api/v1/bookmarks/:id - Updates an existing bookmark's title and/or tags.
   *
   * @param req - Express request containing bookmark ID in params and updates in body.
   * @param res - Express response sending updated bookmark or error status.
   * @param next - Express next middleware function for validation error delegation.
   * @returns Void.
   *
   * @example
   * ```ts
   * // PATCH /api/v1/bookmarks/123e4567-e89b-12d3-a456-426614174000
   * // Body: { "title": "New Title" }
   * router.patch('/:id', updateBookmarkHandler);
   * ```
   */
  function updateBookmarkHandler(req: Request<{ id: string }>, res: Response, next: NextFunction): void {
    const rawId = req.params.id;
    const id = typeof rawId === 'string' ? rawId : Array.isArray(rawId) ? rawId[0] : '';

    if (!id) {
      res.status(404).json({
        error: 'Not Found',
        message: 'Bookmark not found',
      });
      return;
    }

    const body: unknown = req.body;
    if (typeof body === 'object' && body !== null && 'url' in body && (body as Record<string, unknown>).url !== undefined) {
      res.status(400).json({
        error: 'URL is immutable and cannot be updated',
      });
      return;
    }

    const parseResult = updateBookmarkSchema.safeParse(body);
    if (!parseResult.success) {
      next(parseResult.error);
      return;
    }

    const updated = service.update(id, parseResult.data);
    if (!updated) {
      res.status(404).json({
        error: 'Not Found',
        message: `Bookmark with id "${id}" not found`,
      });
      return;
    }

    res.status(200).json(updated);
  }

  /**
   * Handles DELETE /api/v1/bookmarks/:id - Deletes a bookmark by ID.
   *
   * @param req - Express request containing bookmark ID parameter.
   * @param res - Express response sending 204 No Content or 404 Not Found.
   * @returns Void.
   *
   * @example
   * ```ts
   * // DELETE /api/v1/bookmarks/123e4567-e89b-12d3-a456-426614174000
   * router.delete('/:id', deleteBookmarkHandler);
   * ```
   */
  function deleteBookmarkHandler(req: Request<{ id: string }>, res: Response): void {
    const rawId = req.params.id;
    const id = typeof rawId === 'string' ? rawId : Array.isArray(rawId) ? rawId[0] : '';

    if (!id) {
      res.status(404).json({
        error: 'Not Found',
        message: 'Bookmark not found',
      });
      return;
    }

    const deleted = service.delete(id);
    if (!deleted) {
      res.status(404).json({
        error: 'Not Found',
        message: `Bookmark with id "${id}" not found`,
      });
      return;
    }

    res.status(204).send();
  }

  router.get(['/', '/api/v1/bookmarks'], listBookmarksHandler);
  router.get(['/search', '/api/v1/bookmarks/search'], searchBookmarksHandler);
  router.get(['/:id', '/api/v1/bookmarks/:id'], getBookmarkByIdHandler);
  router.post(['/', '/api/v1/bookmarks'], createBookmarkHandler);
  router.patch(['/:id', '/api/v1/bookmarks/:id'], updateBookmarkHandler);
  router.delete(['/:id', '/api/v1/bookmarks/:id'], deleteBookmarkHandler);

  return router;
}

export const bookmarksRouter = createBookmarksRouter(bookmarkService);

export default bookmarksRouter;

